-- Ficha de La India Canela.
--
-- Nombre legal Lidia María Hernández López (Smithsonian Folkways 2008, Wikipedia); Mery Hernández
-- como alias (El Día 2023, Granma 2007). Lugar de nacimiento: El Limón, Villa González, Santiago
-- (la fila decía Santiago Rodríguez). occupations: accordionist, bandleader, songwriter (sustituye
-- musician). instruments: accordion. Sin premios: los dos Casandra no tienen año en ninguna fuente.

UPDATE artists SET first_name = 'Lidia', middle_name = 'María', last_name = 'Hernández',
       second_last_name = 'López', birth_place = 'Villa González', province = 'Santiago',
       occupations = '["accordionist","bandleader","songwriter"]'::jsonb, instruments = ARRAY['accordion']::text[], aliases = ARRAY['Mery Hernández']::text[]
 WHERE slug = 'la-india-canela';

